            EventTypeRepository = new Repository<EventType>(context);
            menuButtonRepository = new Repository<MenuButton>(context);
            menuButtonGroupRepository = new Repository<MenuButtonGroup>(context);
            FeaturesRepository = new Repository<Feature>(context);
            EntityStatusRepository = new Repository<EntityStatus>(context);


             ObjectTables = ObjectTableRepository.GetAll(0).ToDictionary(d => d.Name, a => a);
            ObjectTable generalTable = ObjectTables["General"];
            TextCodes = TextCodeRepository.GetAll(0).Where(t => t.ObjectTableId == generalTable.Id).ToDictionary(d => d.Code + d.Tenant.ToString() + d.ObjectTableId, a => a, StringComparer.OrdinalIgnoreCase);
			TenantFeatures = FeaturesRepository.GetAll(0).Where(t => t.ObjectTableId == generalTable.Id).ToDictionary(d => d.Code + d.ObjectTableId, a => a);
