			TenantObjectTableTabs = new Dictionary<string, ObjectTableTab>();
			tenantEventTypes = EventTypeRepository.GetAll(0).ToDictionary(d => d.Code + d.ObjectTableId, a => a);
			tenantMenuButtons = new Dictionary<string, MenuButton>();
			tenantMenuButtonGroups = menuButtonGroupRepository.GetAll(0).ToDictionary(d => d.Name, a => a);
			AllEntityStatuses = EntityStatusRepository.GetAll(0).ToList();
			tenantQueryGroups = queryGroupRepository.GetQueryable().ToDictionary(d => d.Code, a => a);	


			 MetadataUpdateUtility.RunPreDeleteProcedure(contextTenant);

			 CreateAllObjectTablesMetadata(contextTenant);
			 
 
			 this.ObjectContext.SaveChanges();
			 if(runPostDeleteProcedure)
			 {
				MetadataUpdateUtility.RunPostDeleteProcedure(contextTenant);
			 }
			
        }

